SELECT id, merchant, DENSE_RANK() OVER w_ordered AS amount_dense_rank, AVG(amount) OVER (PARTITION BY account_id, merchant ORDER BY txn_time, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS amount_avg_3_prior, LAST_VALUE(amount, TRUE) OVER (PARTITION BY txn_type ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, DENSE_RANK() OVER w_grp AS amount_dense_rank_2, ROW_NUMBER() OVER (PARTITION BY account_id, merchant ORDER BY txn_time, id) AS event_seq FROM transactions WINDOW w_ordered AS (ORDER BY amount DESC NULLS LAST), w_grp AS (PARTITION BY merchant ORDER BY amount)
